create table public.fechou_workspaces (id uuid primary key default gen_random_uuid(), name text not null check(char_length(trim(name)) between 1 and 120), created_at timestamptz not null default now());
grant select on public.fechou_workspaces to authenticated;
grant all on public.fechou_workspaces to service_role;
alter table public.fechou_workspaces enable row level security;
create table public.fechou_members (workspace_id uuid not null references public.fechou_workspaces(id), user_id uuid not null, name text not null, role text not null check(role in ('admin','manager','seller')), primary key(workspace_id,user_id));
grant select on public.fechou_members to authenticated;
grant all on public.fechou_members to service_role;
alter table public.fechou_members enable row level security;
create function public.fechou_role(p_workspace uuid) returns text language sql stable security definer set search_path='' as $$ select role from public.fechou_members where workspace_id=p_workspace and user_id=(select auth.uid()) and (select auth.jwt()->>'aal')='aal2' $$;
revoke all on function public.fechou_role(uuid) from public, anon;
grant execute on function public.fechou_role(uuid) to authenticated;
create policy fechou_workspaces_read on public.fechou_workspaces for select to authenticated using(public.fechou_role(id) is not null);
create policy fechou_members_read on public.fechou_members for select to authenticated using(public.fechou_role(workspace_id) in ('admin','manager') or (public.fechou_role(workspace_id) is not null and user_id=(select auth.uid())));
create table public.fechou_stages (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.fechou_workspaces(id), name text not null check(char_length(trim(name)) between 1 and 60), position integer not null, kind text not null default 'open' check(kind in ('open','won','lost')), target_days integer not null default 3 check(target_days between 1 and 365), unique(workspace_id,id), unique(workspace_id,position));
grant select on public.fechou_stages to authenticated;
grant update(name,target_days) on public.fechou_stages to authenticated;
grant all on public.fechou_stages to service_role;
alter table public.fechou_stages enable row level security;
create policy fechou_stages_read on public.fechou_stages for select to authenticated using(public.fechou_role(workspace_id) is not null);
create policy fechou_stages_update on public.fechou_stages for update to authenticated using(public.fechou_role(workspace_id) in ('admin','manager')) with check(public.fechou_role(workspace_id) in ('admin','manager'));
create table public.fechou_deals (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.fechou_workspaces(id), owner_id uuid not null, stage_id uuid not null, company text not null check(char_length(trim(company)) between 1 and 160), contact text not null default '', email text not null default '', phone text not null default '', segment text not null default '', linkedin text not null default '', instagram text not null default '', founded_on date, birth_date date, notes text not null default '', amount numeric(14,2) not null default 0 check(amount >= 0 and amount < 1000000000000), entered_at timestamptz not null default now(), created_at timestamptz not null default now(), foreign key(workspace_id,stage_id) references public.fechou_stages(workspace_id,id), foreign key(workspace_id,owner_id) references public.fechou_members(workspace_id,user_id));
grant select on public.fechou_deals to authenticated;
grant insert(workspace_id,owner_id,stage_id,company,contact,email,phone,segment,linkedin,instagram,founded_on,birth_date,notes,amount) on public.fechou_deals to authenticated;
grant update(owner_id,stage_id,company,contact,email,phone,segment,linkedin,instagram,founded_on,birth_date,notes,amount) on public.fechou_deals to authenticated;
grant all on public.fechou_deals to service_role;
alter table public.fechou_deals enable row level security;
create policy fechou_deals_read on public.fechou_deals for select to authenticated using(public.fechou_role(workspace_id) in ('admin','manager') or (owner_id=(select auth.uid()) and public.fechou_role(workspace_id)='seller'));
create policy fechou_deals_insert on public.fechou_deals for insert to authenticated with check(public.fechou_role(workspace_id) in ('admin','manager') or (owner_id=(select auth.uid()) and public.fechou_role(workspace_id)='seller'));
create policy fechou_deals_update on public.fechou_deals for update to authenticated using(public.fechou_role(workspace_id) in ('admin','manager') or (owner_id=(select auth.uid()) and public.fechou_role(workspace_id)='seller')) with check(public.fechou_role(workspace_id) in ('admin','manager') or (owner_id=(select auth.uid()) and public.fechou_role(workspace_id)='seller'));
create index fechou_deals_workspace_owner on public.fechou_deals(workspace_id,owner_id);
create table public.fechou_goals (workspace_id uuid not null references public.fechou_workspaces(id), owner_id uuid not null, period date not null check(extract(day from period)=1), amount numeric(14,2) not null check(amount > 0 and amount < 1000000000000), primary key(workspace_id,owner_id,period), foreign key(workspace_id,owner_id) references public.fechou_members(workspace_id,user_id));
grant select,insert,update on public.fechou_goals to authenticated;
grant all on public.fechou_goals to service_role;
alter table public.fechou_goals enable row level security;
create policy fechou_goals_read on public.fechou_goals for select to authenticated using(public.fechou_role(workspace_id) in ('admin','manager') or (owner_id=(select auth.uid()) and public.fechou_role(workspace_id)='seller'));
create policy fechou_goals_insert on public.fechou_goals for insert to authenticated with check(public.fechou_role(workspace_id) in ('admin','manager'));
create policy fechou_goals_update on public.fechou_goals for update to authenticated using(public.fechou_role(workspace_id) in ('admin','manager')) with check(public.fechou_role(workspace_id) in ('admin','manager'));
create table public.fechou_audit (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.fechou_workspaces(id), actor_id uuid, record_id uuid not null, action text not null, created_at timestamptz not null default now());
grant select on public.fechou_audit to authenticated;
grant all on public.fechou_audit to service_role;
alter table public.fechou_audit enable row level security;
create policy fechou_audit_read on public.fechou_audit for select to authenticated using(public.fechou_role(workspace_id) in ('admin','manager'));
create function public.fechou_track_deal() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_op='UPDATE' and new.stage_id is distinct from old.stage_id then new.entered_at=now(); end if; insert into public.fechou_audit(workspace_id,actor_id,record_id,action) values(new.workspace_id,auth.uid(),new.id,case when tg_op='INSERT' then 'created' when new.stage_id is distinct from old.stage_id then 'stage_changed' else 'updated' end); return new; end; $$;
revoke all on function public.fechou_track_deal() from public, anon, authenticated;
create trigger fechou_track_deal before insert or update on public.fechou_deals for each row execute function public.fechou_track_deal();
create function public.fechou_create_workspace(p_name text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; v_user uuid:=auth.uid(); begin if v_user is null or auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'Confirme a verificação em duas etapas.'; end if; insert into public.fechou_workspaces(name) values(trim(p_name)) returning id into v_id; insert into public.fechou_members values(v_id,v_user,coalesce(auth.jwt()->>'email','Administrador'),'admin'); insert into public.fechou_stages(workspace_id,name,position,kind,target_days) values(v_id,'Prospecção',1,'open',3),(v_id,'Qualificação',2,'open',5),(v_id,'Proposta',3,'open',7),(v_id,'Negociação',4,'open',5),(v_id,'Ganho',5,'won',3),(v_id,'Perdido',6,'lost',3); return v_id; end $$;
revoke all on function public.fechou_create_workspace(text) from public, anon;
grant execute on function public.fechou_create_workspace(text) to authenticated;
create function public.fechou_add_member(p_workspace uuid,p_email text,p_name text,p_role text) returns void language plpgsql security definer set search_path='' as $$ declare v_user uuid; begin if public.fechou_role(p_workspace) is distinct from 'admin' then raise exception 'Somente administradores podem cadastrar acessos.'; end if; if p_role is null or p_role not in ('manager','seller') or p_name is null or char_length(trim(p_name)) not between 1 and 120 then raise exception 'Confira nome e cargo.'; end if; select id into v_user from auth.users where lower(email)=lower(trim(p_email)) and email_confirmed_at is not null limit 1; if v_user is null then raise exception 'A conta precisa existir e ter o e-mail confirmado.'; end if; insert into public.fechou_members values(p_workspace,v_user,trim(p_name),p_role); insert into public.fechou_audit(workspace_id,actor_id,record_id,action) values(p_workspace,auth.uid(),v_user,'member_added'); end $$;
revoke all on function public.fechou_add_member(uuid,text,text,text) from public, anon;
grant execute on function public.fechou_add_member(uuid,text,text,text) to authenticated;